#!/usr/bin/env bash
# generated by grippd 0.1.0 from grippd.yaml. Don't edit: change grippd.yaml and grippd regenerates this file.
# Usage: mint.sh <app> <environment> <job>
# Swaps this job's GitHub OIDC token for a key grippd mints for one app, one environment and
# one job, then exports it (masked) to the steps after this one. The key expires on its own.
set -euo pipefail
app=$1 env=$2 job=$3
oidc=$(curl -fsS -H "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
  "$ACTIONS_ID_TOKEN_REQUEST_URL&audience=https://api.grippd.sh" | jq -r .value)
resp=$(curl -fsS -X POST "https://api.grippd.sh/v1/projects/$GRIPPD_PROJECT/keys" \
  -H "Authorization: Bearer $oidc" -H "Content-Type: application/json" \
  -d "$(jq -n --arg app "$app" --arg env "$env" --arg job "$job" '{app: $app, env: $env, job: $job, ttl: "15m"}')")
# grippd returns the environment variables this job needs: GRIPPD_UPLOAD_TOKEN to upload
# builds, or TURBO_TOKEN plus TURBO_REMOTE_CACHE_SIGNATURE_KEY for the Turborepo cache.
# Keys that deploy, migrate or change infrastructure are never minted to CI.
while IFS='=' read -r k v; do
  echo "::add-mask::$v"
  echo "$k=$v" >> "$GITHUB_ENV"
done < <(jq -r '.env | to_entries[] | "\(.key)=\(.value)"' <<<"$resp")
echo "Minted a $job key for $app in $env, expires $(jq -r .expires_at <<<"$resp")"
